/**
 * Syllabus — subject & topic weightages verified against 2022–2026 audit.
 * Fully expanded with granular, atomic subtopics and dedicated chapters
 * corresponding to the official GATE Computer Science & Information Technology syllabus.
 * See src/lib/data/verifiedPapers.ts for canonical 8-paper dataset.
 */
export type TopicStatus = 'not_started' | 'in_progress' | 'completed' | 'mastered'

export interface YearMarks {
  year: number
  marks: number
  questions: number
}

export interface Topic {
  id: string
  name: string
  chapter?: string
  status: TopicStatus
  hours: number
  weightage: number
  prerequisites: string[]
  frequency: 'very_high' | 'high' | 'medium' | 'low'
  avgMarks: number
  yearMarks: YearMarks[]
}

export interface Subject {
  id: string
  name: string
  shortName: string
  weightage: number
  color: string
  topics: Topic[]
  yearMarks: YearMarks[]
  avgMarks: number
  volatility: 'stable' | 'moderate' | 'volatile'
  trend: 'up' | 'down' | 'stable'
}

// Alias for backward compatibility
export type Section = Subject

